patterns=[
    re.compile(r'Appeals? from the United States District Court\\s+for the\\s+([A-Z][A-Za-z .\\-]+?(?:District of [A-Z][A-Za-z .\\-]+|[A-Z][A-Za-z .\\-]+ District of [A-Z][A-Za-z .\\-]+|District of Columbia))(?=[\\s,.;])', re.I|re.S),
    re.compile(r'Appeals? from the United States District Court\\s+([A-Z][A-Za-z .\\-]+?(?:District of [A-Z][A-Za-z .\\-]+|[A-Z][A-Za-z .\\-]+ District of [A-Z][A-Za-z .\\-]+|District of Columbia))(?=[\\s,.;])', re.I|re.S),
    re.compile(r'Appeals? from the District Court\\s+for the\\s+([A-Z][A-Za-z .\\-]+?(?:District of [A-Z][A-Za-z .\\-]+|District of Columbia))(?=[\\s,.;])', re.I|re.S),
    re.compile(r'Appeals? from the District Court\\s+([A-Z][A-Za-z .\\-]+?(?:District of [A-Za-z .\\-]+|District of Columbia))(?=[\\s,.;])', re.I|re.S),
    re.compile(r'Appeals? from the District of Northern Mariana Islands', re.I|re.S),
]

matched=[]
unmatched=[]
