            if m.lastindex:
                ans=clean(m.group(1))
            else:
                ans='District of Northern Mariana Islands'
            src=clean(m.group(0))
            break
    if ans:
        matched.append((doc['doc_name'], ans, src))
    else:
        unmatched.append(doc)
print('matched', len(matched), 'unmatched', len(unmatched))
print('\\nunique matched courts', len(collections.Counter(a for _,a,_ in matched)))
for name,ans,src in matched[:20]:
    print(name, '=>', ans, '|', src)
print('\\nfirst 40 unmatched:')
for doc in unmatched[:40]:
    txt=open(doc['doc_path'], errors='ignore').read().splitlines()[:90]
    print('\\n###', doc['doc_name'])
    for i,l in enumerate(txt,1):
        if re.search(r'Appeal|District Court|petition|Board of Immigration Appeals|rehearing|mandamus|Ninth Circuit', l, re.I):
            print(f'{i}: {l}')
